//! 🧪️ Queue admission keeps original inputs until the same paid frame and placement succeed.
use semio_framework_value_retirement_queue::*;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]
fn resident_queue_admission_prices_both_actions_and_preserves_null_input(){
 let law:serde_json::Value=serde_json::from_str(include_str!("fixture.json")).unwrap();let mut queue=RetirementQueue::default();let mut born=0;for _ in 0..32{if queue.has_reserved_slot(){break}let d=queue.reserve_demand().unwrap();let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant(d),1,&mut actual);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||queue.reserve_step(&mut effect));let p=turn.result.unwrap();assert_eq!(heap,(p.retained_capacity_bytes,0));assert!(p.fits(grant(d)));born+=heap.0;}assert!(queue.has_reserved_slot());
 let mut original=Some(41u64);let d=queue.admit_owned_demand(original.as_ref().unwrap()).unwrap();for row in law["refusals"].as_array().unwrap(){let mut g=grant(d);if !row["copyAllowed"].as_bool().unwrap(){g.maximum_copy_bytes=0}let mut actual=None;let mut effect=RetainedAllocationEffect::new(g,row["work"].as_u64().unwrap(),&mut actual);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||queue.admit_owned(&mut original,&mut effect));assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(original,Some(41));assert_eq!(queue.len(),0)}
 let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant(d),2,&mut actual);let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||queue.admit_owned(&mut original,&mut effect)));assert_eq!(attempts,1);assert_eq!(turn.work,law["nullWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0));assert_eq!(original,Some(41));assert_eq!(queue.len(),0);
 let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant(d),2,&mut actual);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||queue.admit_owned(&mut original,&mut effect));let p=turn.result.unwrap().unwrap();assert_eq!(turn.work,law["admissionWork"].as_u64().unwrap());assert_eq!(heap,(d.capacity_bytes,0));assert_eq!(actual,Some(d.capacity_bytes));assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(p.retained_capacity_bytes,d.capacity_bytes);assert!(original.is_none());assert_eq!(queue.len(),1);born+=heap.0;
 let mut released=0;for _ in 0..128{if queue.terminal_is_empty(){break}let d=queue.next_demand(4096).unwrap();let units=queue.next_computational_work(4096).unwrap();let mut actual=None;let mut effect=RetainedAllocationEffect::new(grant(d),units,&mut actual);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||queue.step(&mut effect));let p=turn.result.unwrap().progress();assert!(p.fits(grant(d)));assert!(turn.work<=units);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));released+=p.released_bytes;born+=p.retained_capacity_bytes;}assert!(queue.terminal_is_empty());assert_eq!(released,born);
}
